#!/usr/bin/env node
/**
 * Bundle public/js/schedule/*.js → public/js/schedule.js (single IIFE)
 */
const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, '..', 'public', 'js', 'schedule');
const out = path.join(__dirname, '..', 'public', 'js', 'schedule.js');
const files = fs.readdirSync(dir).filter(f => f.endsWith('.js')).sort();

const bodies = files.map(f => {
  const raw = fs.readFileSync(path.join(dir, f), 'utf8');
  // re-indent 2 spaces for IIFE body
  return raw.split('\n').map(line => (line.length ? '  ' + line : line)).join('\n');
});

const banner = `/* ============================================================
   schedule.js — AUTO-GENERATED from public/js/schedule/*
   Do not edit this file directly; edit parts and run:
     node scripts/bundle-schedule.js
   ============================================================ */

`;

const content = banner + `(function () {
  'use strict';

${bodies.join('\n\n')}
})();
`;

fs.writeFileSync(out, content);
console.log('Bundled', files.length, 'parts →', out, '(' + content.length + ' bytes)');
